mapper.insert:
insert into ai_chat_room (
    member_id,
    title
) values (
    #{memberId},
    #{title}
)

insert into ai_chat_message (
    room_id,
    sender_type,
    message
) values (
    #{roomId},
    #{senderType},
    #{message}
)

mapper.select:
select notice_id as noticeId , title , category , content , created_at as createdAt from notice where status = '게시' and is_public = true
and ( title ilike '%' || #{keyword} || '%' or content ilike '%' || #{keyword} || '%' or category ilike '%' || #{keyword} || '%' )
order by is_pinned desc, created_at desc limit #{limit}

select faq_id as faqId , category , question , answer from faq where is_active = true
and ( question ilike '%' || #{keyword} || '%' or answer ilike '%' || #{keyword} || '%' or category ilike '%' || #{keyword} || '%' )
order by display_order asc, faq_id asc limit #{limit}

select complaint_id as complaintId , title , complaint_type as complaintType , priority , status , station_name as stationName , charger_name as chargerName , ai_summary as aiSummary , admin_memo as adminMemo , created_at as createdAt from complaint where member_id = #{memberId}
and ( title ilike '%' || #{keyword} || '%' or content ilike '%' || #{keyword} || '%' or complaint_type ilike '%' || #{keyword} || '%' or station_name ilike '%' || #{keyword} || '%' or charger_name ilike '%' || #{keyword} || '%' )
order by created_at desc limit #{limit}
